import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    n = int(input_data[0])
    t = input_data[1]
    m = int(input_data[2])

    words_raw = input_data[3:]

    transformed_words = {}

    for w in words_raw:
        w_lower = w.lower()
        rev_w = w_lower[::-1]
        if rev_w not in transformed_words:
            transformed_words[rev_w] = []
        transformed_words[rev_w].append(w)

    dp = [None] * (n + 1)
    parent = [None] * (n + 1)
    word_used = [None] * (n + 1)

    dp[0] = True

    for i in range(n):
        if not dp[i]:
            continue

        for length in range(1, min(1001, n - i + 1)):
            substring = t[i:i+length]
            if substring in transformed_words:
                if dp[i + length] is None:
                    dp[i + length] = True
                    parent[i + length] = i
                    word_used[i + length] = transformed_words[substring][0]

    path = []
    curr = n
    while curr > 0:
        path.append(word_used[curr])
        curr = parent[curr]

    path.reverse()
    print(" ".join(path))

if __name__ == "__main__":
    solve()
